import{_ as a,c as e,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const m=JSON.parse('{"title":"西溪易說卷十一","description":"西溪易說 - 西溪易說卷十一","frontmatter":{"title":"西溪易說卷十一","description":"西溪易說 - 西溪易說卷十一"},"headers":[],"relativePath":"classics/xixi/012.md","filePath":"classics/xixi/012.md"}'),i={name:"classics/xixi/012.md"};function r(c,p,_,o,n,l){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="西溪易說卷十一" tabindex="-1">西溪易說卷十一 <a class="header-anchor" href="#西溪易說卷十一" aria-label="Permalink to “西溪易說卷十一”">​</a></h1><p>欽定四庫全書</p><p>宋李過撰</p><p>䷲ 震上震下</p><p>震</p><p>震：亨。震來虩虩，笑言啞啞。震驚百里，不喪七鬯。彖曰：「震」，亨。「震來虩虩」，恐致福也。「笑言啞啞」，後有則也。「震驚百里」，驚遠而懼邇也。出可以守宗廟社稷，以為祭主也。瀳雷為震。雷，天地之威也，莫震如之。處震驚而不動，然後可以觀人之所養。人固有也，疾雷破山而耳不懾，泰山墮前而目不瞬者，其中有主，而所存者素定也。其義則見於震，曰「震亨」，恐懼而至亨也。虩虩，恐懼貌。當天地動威之時，不可不恐懼，故「震來虩虩」。然君子所履，出處語嘿皆有常則，不可以恐懼而變也，故「笑言啞啞，震驚百里」，震之極也。當其承宗廟祭祀，手執匕鬯以交鬼神，此時此心，純一無間，雖震驚百里而所執不喪也。人心常如執七鬯之時，則天下患難莫之恐懼矣。惟六五爻可以當之。彖曰：「震，亨，震來虩虩，恐致福也。以恐懼而致福也。笑言啞啞，後有則也。」雖處恐懼，而出處語嘿之常則不失也。驚遠懼邇，震之極也。處震之極，而此心不動，則可以守宗廟而主祭矣。此就於不喪匕鬯之中取義也。</p><p>象曰：瀳雷，震；君子以恐懼修省。</p><p>恐懼修省，此心無時而不存也。初九，震來虩虩，後笑言啞啞，吉。象曰：「震來虩虩」，恐致福也；「笑言啞啞」，後有則也。</p><p>震之初，言所以處震之道，已見於彖。</p><p>六二，震來厲，億喪貝，躋於九陵，勿逐，七日得。象曰：「震來厲」，乘剛也。</p><p>雷，陽氣也。陽居初與四為瀳雷，二與三為初所震，五與上為四所震。六二以柔居柔，中無所主者也，為初所震，大喪其所有之貝。互體有艮，升艮之上而至六五，五能無喪，六二之貝既喪而復得。艮少陽，其數七，越艮而得五，是七日也，故曰「躋於九陵，勿逐，七日得」，謂六二中無所守，能如六五之有事，則可以無喪也。象曰「乘剛也」，謂乘初九之剛，為初所震也。</p><p>六三，震蘇蘇，震行無眚。象曰：「震蘇蘇」，位不當也。</p><p>以六居三，其位本危，況處震六，為初所震，氣息僅存，故「震蘇蘇」然。以恐懼而行，亦可無眚，不失為戒謹之事也。象曰「位不當也」，以三位不正也。九四，震遂泥。象曰：「震遂泥」，未光也。</p><p>四處瀳雷，陷互體坎中，「遂泥」之象也。象曰：「未光也」，以中行剛，非善處恐懼者。</p><p>六五，震往來厲，億無喪，有事。象曰：「震往來厲」，危行也；具事在中，大無喪也。</p><p>五為瀳雷所震，初震才往，四震又來，故曰「震往來厲」。以柔處剛，中有所主，故「震」而「無喪」。其所以「無喪」者，以其「有事」也。孟子所謂必有事焉而勿正，曰有事，存養之功也。此心所存，當如執匕鬯之時，則何恐懼之可變？故六五有事，雖瀳雷而不能震也。「不失匕鬯」，此爻當之。象曰：「震往來厲」，危行也；謂莫危於瀳雷也。其事在中，大無喪也。惟此心主一，其中有事，則大無喪也。億，大也。</p><p>上六，震索索，視矍矍，徵㓙。震不於其躬，於其鄰，無咎。婚媾有言。象曰：「震索索」，中未得也；雖「㓙」「無咎」，畏鄰戒也。處震之極，為瀳雷所恐，故「索索」而又「矍矍」。驚懼如此，徵則必㓙然。四震在五，非震六也。震不在己之躬，而在己之鄰，因鄰致戒，可以「無咎」。蓋恐懼戒謹，不失為謹獨之學也。己應在三，「婚媾」也。三居坎下，「坎」為「小有言」，三「震蘇蘇」，豈能救己，所以「有言」。象曰：「震索索」，中未得也。以中未有所得，故其「恐索索」。雖㓙「無咎」，畏鄰戒也。「兇」而「無咎」者，因鄰致戒，聖人與之。䷳ 艮下艮下</p><p>「艮」。</p><p>艮其背，不獲其身；行其庭，不見其人，無咎。彖曰：「艮」，止也。時止則止，時行則行，動靜不失其時，其道光明。艮其止，止其所也。上下敵應，不相與也，是以「不獲其身，行其庭，不見其人，無咎」也。</p><p>艮，止也，止其所而不與物接也。不與物接，則與物背，故但見其背而已。鹹與物感，故鹹卦六爻言人之前；艮與物背，故艮卦六爻言人之背。曰：</p><p>「艮其背，不獲其身；行其庭，不見其人。」既與物背，人所見者背而已，是以「不獲其身」也。庭者，交際之所。既與物背，雖行於交際之所，亦不得見其人也。彖曰：「時止則止，時行則行，動靜不失其時，其道光明。」艮固止也，然亦不終止，可以出則出，可以處則處，各當其時之可而已，故曰「不失其時，其道光明」。聖人此意，於學者深有功。艮其止，止其所也。萬物各有所止，能止於當止之所，則止道得矣。上下六爻，剛柔不能相應，無相與之義。惟不相與，故與物背而但見其背；惟其如是，故「不獲其身，行其庭不見其人，無咎」也。象曰：兼山，「艮」，君子以思不出其位。</p><p>言止其所也。如立天下之正位，素其位而行，不在其位，不謀其政，皆位也。</p><p>初六，艮其趾，無咎，利貞。象曰：「艮其止」，未失正也。</p><p>六爻背，言人之背以止為義，欲趾而不欲動，趾在下而不動，則「無咎」。利永貞。人有止於暫而不能止於久者，非善止也，故曰「利永貞」。象曰「未失正也」。能止於初，故未有失。六二，艮其腓，不拯其隨，其心不快。象曰：「不拯其隨」，未退聽也。</p><p>二居止上，腓也，物在前而足向後，但見其腓而已與物背，故不拯而隨物。然心固難持也，足雖不拯而心常不快，故止不在腓而在心，心止則腓止，是止腓之道也。象曰「未退聽也」，言未正心而正腓，故腓未退聽也。</p><p>九三，艮其限，列其夤，厲薰心。象曰：「艮其限」，危薰心也。限者，背之下，股之上，腰折處也。夤，累肉也。人身欲轉，力在夤限，三位當之，故「艮其限，列其夤」，使不相屬。所以然者，恐行與物接，則危懼足以薰心也。蓋蹶者趨者是氣也，而足以反動其心也。象曰：「艮其限，危薰心也」，恐危懼薰汝心也。</p><p>六四，艮其身，無咎。象曰：「艮其身」，止諸躬也。</p><p>四在夤上，通以身言之，身既止，則止其所矣，象曰：「止諸躬也」。六五，艮其輔，言有序，悔亡。象曰：「艮其輔」，以中正也。五處躬上，輔，頰之兩旁骨，背後可得而見者。鹹說前，故並見頰舌；艮說後，故止見其輔。口言則輔動，輔止則言寡，故「言有序」，象曰「以中正也」，止而至此，得止之正矣。</p><p>上九：敦艮，吉。象曰：「敦艮」之吉，以厚終也。</p><p>自趾之輔皆得所止，則止道厚矣。故艮之終，但贊以厚艮吉。象曰：「敦艮」之吉，以厚終矣。易中惟鹹與艮言人之身，鹹言人前，艮言人背。艮卦「艮其腓」，鹹卦「鹹其腓」，鹹卦「鹹其輔」，艮亦「艮其輔」。蓋腓雖在後，前可得而見，故鹹卦得兼艮之腓。輔雖在前，後可得而見，故艮卦得兼鹹之輔。䷴ 艮下巽上</p><p>漸</p><p>漸：女歸吉，利貞。彖曰：漸之進也。「女歸吉」也。進得位，往有功也。進以正，可以正邦也。其位，剛得中也。止而巽，動不窮也。漸，進以漸也。止而巽，漸之義也。水之流也以漸，木之生也以漸，鴻之飛也亦以漸。至漸莫如水而木漸，鴻漸如之。象取木漸，以二體言之。六爻則取「鴻漸」，以物之有德者言也。自初漸於幹，以次至五，乃漸於陵，此言漸進之義，而鴻之德則在上爻。鴻漸於陸，君子恥一物之不知。論格物之學，未有如易之盡者，觀漸可見。卦辭曰：「女歸吉。」進之漸，莫如歸女。女子從人，必待六禮之備，至不苟也。納吉、納彩、問名、納幣、請期、親迎，各有其序，不可遽合也。卦則九居五，夫道也；六居二，婦道也。二進歸五，如鴻之漸，故曰「漸，女歸吉，利貞」，進以正也。彖：「進得位」，往有功也；「其位」，剛得中也；指二五言也。「進以正」，可以正邦也。未有己不正而能正人者也。止而「巽」，動不窮也。止於其所以順往，則得動靜之時，故其動不窮。此漸進之義，所謂非其往不往，非其居不居之意也。</p><p>象曰：山上有木，「漸」，君子以居賢德善俗。木之生也，其進必以漸。善俗之道，要非一日。王豹處於淇而河西善謳，杞梁之妻善哭其夫而變國俗，漸之道蓋如此。</p><p>初六，鴻漸於幹，小子厲，有言無咎。象曰：「小子」之「厲」，義無咎也。</p><p>鴻，物之隨陽者也。寒氣復，則自北而南，其來也必以漸。六爻設「鴻漸」，最有綱領。就物理觀之，鴻之飛，其群不亂，其長幼有序，其飲食不貪，其夫婦相保，其防患有道，此物之有德者也。據六爻列鴻於上，群雁也。鴻之飛，長在前而幼在後，此其序也。「幹」，水湄也。初漸於幹，以次而進，所謂非其居而不居也。初處最下，小子也。「厲」，危也。鴻之進也，常有弓繳之危，故「小子厲有言」，遇有危事，則鴻以警眾，即俗語「爾為鴈奴」是也。其防患有道，故雖危無咎。象曰：「小子」之厲，義「無咎」也。防患如此，宜其「無咎」也。</p><p>六二，鴻漸於磐，飲食衎衎，吉。象曰：「飲食衎衎」，不素飽也。磐，水中之石。二進至磐，止而食也，所謂「君看隨陽雁，各有稻粱謀」是也。然鴻食則呼眾，故「飲食衎衎」和鳴也。象曰：「不素飽也」，言共飲食，不貪也。</p><p>九三，鴻漸於陸，夫徵不復，婦孕不育，兇。利用禦寇。象曰：「夫徵不復」，離群醜也；「婦孕不育」，失其道也；「利用禦寇」，順相保也。</p><p>陸，平地，鴻之所遵也。三進至陸，雁為陽鳥，卦中三陽，上與五在前，九三處二陰之問，失群雁也，所謂「誰憐一片影，相失萬重雲」者也。應在上，夫也，往而不復；已，婦也，失配，故孕而不育。然雁群不亂，止則相保，故「利用禦寇」，不可他配也。象曰「離群醜也」，言上九離其類而去也。「婦孕不育，失其道也」，失陰陽之道也。「利用禦寇，順相保也」，謂上九依前漸陸而相保也。</p><p>六四，鴻漸於木，或得其桷，無咎。象曰：「或得其桷」，順以巽也。</p><p>四進至木，居巽體，巽為木，鴈足有幕，不能爪木。桷，木之平處，故亦可止。巽體順，故為得桷，象曰「順以巽也」。</p><p>九五，鴻漸於陵，婦三歲不孕，終莫之勝，吉。象曰：「終莫之勝吉」，得所願也。</p><p>五漸至陵，二已應也，在後不孕，然女歸以漸，故「終莫之勝」，象曰「得所願也」。</p><p>上九，鴻漸於陸，其羽可用為儀，吉。象曰：「其羽可用為儀，吉」，不可亂也。</p><p>飛極則止。上應在三，依前遵陸，以求己配。蓋其群不亂，鴻之德也。聖人觀此羽毛，其飛有序，其止有所，其飲食不飽、其群不亂，其夫婦相保，其防患又有道，是物之有知而又有義者也，故可用以為儀，如贄見執鴈、婚禮奠鴈之類，謂其德可以配禮也。象曰「不可亂也」。三言「順相保」，上言「不可亂」，於此可觀物理。䷵ 兌下震上 歸妹。</p><p>歸妹，徵㓙，無攸利。彖曰：歸妹，天地之大義也。天地不交而萬物不興。歸妹，人之終始也。說以動，所歸妹也。徵㓙，位不當也。「無攸利」，柔乘剛也。</p><p>鹹言取女，漸言女歸，又說歸妹，何也？歸妹，歸娣也。古者諸侯一娶九女，以娣從之，無娣則以侄從。故一國之女不以異姓，娣之年未及，則待年於父母之邦，及期然後逆以歸。故「歸妹，人之終也」，謂嫡婦已久，侄娣之媵待年而歸，既歸則終事也。然娣媵之歸，必以禮逆。女子從人，其歸以漸，不待禮而進，非夫婦之義，故曰「徵㓙」。「歸妹」之禮，不能如嫡，故曰「無攸利」。彖：古人「歸妹」，蓋廣繼嗣之道，故曰「天地之大義」也。天地不交而萬物不興，男女不交而萬物不生，曰「歸妹」，人之終始也。嫡既歸矣，繼以娣媵，終事也，故曰「人之終始」。兌說而震動，「歸妹」之義也。媵道居五，禮逆後歸，餘爻未逆，義不當歸，故曰「位不當」也。以六居五，其袂雖良，其禮則殺，故曰「無攸利」，柔乘剛也。</p><p>象曰：澤上有雷，「歸妹」；君子以永終知敝。</p><p>澤上有雷，水氣隨之而升，則陰陽和而為雨矣，是「天地之交，歸妹」之象也。「歸妹」者，人道終始，故「君子以永終知敝」。</p><p>初九，歸妹以娣，跛能履，徵吉。象曰：「歸妹以娣」，以恆也；「跛能吉」，相承也。</p><p>初處兌下，「兌」為少女，娣之象也；兌為毀折，跛之象也。為其非嫡，宜示不足，如「跛能履」，以此往則吉，謂能自降於嫡也。象曰「以常」者，謂此是天子諸侯之常道也。「吉相承」者，以其嫡媵之相承，所以「吉」也。九二，眇能視，利幽人之貞。象曰：「利幽人之貞」，未變常也。二應在五而五歸之，五柔二剛，故戒以「眇能視」，謂非可以與嫡並，宜示不足，如眇能視，以幽人之道自守則吉。象曰「未變常也」，謂以義分自守也。</p><p>六三，歸妹以須，反歸以娣。象曰：「歸妹以須」，未當也。三年未及而欲歸者也。須，待也，謂年未及尚待年也，俟嫡反歸而以娣行，方可往也。象曰「未當也」，言未當歸也。九四，歸妹愆期，遲歸有時。象曰：「愆期」之志，有待而行也。四年已及而未歸者也，故曰「愆期」，然其歸亦有時矣，謂其歸亦不久也。象曰：「愆期」之志，有待而行也。</p><p>六五，帝乙歸妹，其君之袂不如其娣之袂良，月幾望，吉。象曰：「帝乙歸妹，不如其娣之袂良」也，其位在中，以貴行也。</p><p>五，歸妹之主。君，嫡也。其娣新歸，故其嫡之袂不如新歸之袂良。人情喜新厭舊，故幾望則吉，謂於禮宜殺也，望則與嫡敵體矣。象曰：其位在中，以貴行也。「歸妹」在五，歸而從君，是以貴行也。</p><p>上六：女承筐，無實，士刲羊，無血，無攸利。象曰：上六「無實」，承虛筐也。</p><p>「無實」、「無血」，謂非嫡也。筐者，所以承告虔之物也。「承筐無實」，不贄見也。士，謂夫也，殺生所以告廟也。血毛必具。「刲羊無血」，不告廟也，以其歸也。不贄見，不告廟，所以「無實」、「無血」也。為設嫡媵之禮，使知貴賤等數之異。三代盛時，為娣媵者能以義命自守，而無上僭之敝者，以禮教素明也。故聖人于歸妹上爻特設其義，其意遠矣。象曰：上六「無實」，承虛筐也。䷶ 離下震上</p><p>豐，</p><p>豐：亨，王假之。勿憂，宜日中。彖曰：豐，大也。明以動，故豐。「王假之」，尚大也。「勿憂，宜日中」，宜照天下也。日中則昃，月盈則食，天地盈虛，與時消息，而況於人乎？況於鬼神乎？「豐，大也」，言光明盛大之時也。卦震上離下，六五之君，出震在上，天下之明皆歸之，故豐曰「豐亨」，大而亨也。「王假之」，謂王者當天而假此也。「勿憂」，天下無虞也。宜日中：日，君象也。日之方中，天下無不被其照臨，有日中之主在上，則天下常如「豐亨」之時也。彖：豐，大也。明以動，故豐。天下盛大之時，設施注措，無不光明，故「明以動，故豐」也。皆王者積累艱難之所至，故曰「尚大也」。日中之主在上，天下皆在臨照，則能有其豐矣，故曰「宜照天下」也。治亂安危，與世推移。日中之主，不常出也。大弊極壞之形，常出於「豐亨豫大」之後，故曰「日中則昃，月盈則食，天地盈虛，與時消息」。此理也，雖天地如之，人與神安得而違也？故曰「而況於人乎？況於鬼神乎」？以卦辭言「宜日中」，故彖重發此意，以為後世習治者之戒。</p><p>象曰：雷電皆至，「豐」；君子以折獄致刑。</p><p>雷，天地盛太之氣也；電，天地光明之氣也。盛大光明，豐亨之象也。為豐之主，體光明之氣以「折獄」，體盛大之氣以致刑。「折獄致刑」，明以動者之事也。</p><p>初九，遇其配主，雖旬無咎，往有尚。象曰：「雖旬無咎」，遇旬災也。</p><p>豐卦六爻以五為主。日中之主在五，上下五爻皆當歸五。初處五遠，以九求六。配主也，謂剛柔相配也。下體「離」，「離」數八，越四而得五，旬日方遇也。苟往而得君，雖旬無咎，但往則有尚。象曰：過旬災也。過旬而不至，則必有災，蓋求主不可後也。六二，豐其蔀，日中見鬥，往得疑疾，有孚發若，吉。象曰：「有孚發若」，信以發志也。</p><p>二，離體在下。六五，日中之主也。日中之主在上，豈容在下者得耀其明？「豐其蔀」，自蔽其明也。蓋五日既中，見己之明，猶鬥之明也。然當日之中，鬥安得明？所謂日月出而爝火息也。遽以明往，其君必疑。君德既孚，然後發己之志以上應，則得吉。象曰：信以發志也。</p><p>九三，豐其沛，日中見沬。折其右肱，無咎。象曰：「豐其沛」，不可大事也；「折其右肱」，終不可用也。</p><p>三居下卦之上，在下而得民者也，欲自施沛澤以妝眾心，故曰「豐其沛」。然日中之主在上，豈容三施澤？但見其如水之沬然，自當消鑠也，所謂「雨雪瀌瀌，見睍曰消」者也。苟欲無咎，勢當自傷以示無用然後可，故曰「折其右肱，無咎」。象曰：「豐其沛，不可大事也」，蓋小之也。「折其右肱，終不可用也」，謂其自傷以求免禍。</p><p>九四，豐其蔀，日中見鬥，遇其夷主，吉。象曰：「豐其蔀」，位不當也；「日中見鬥」，幽不明也；「遇其夷主」，吉行也。</p><p>四近五，居大臣之位，依日月之光可也，亦當先自蔽其明。日既中矣，見四之明，亦如斗然。夷，平也，謂六五也。以六居五，為夷平之主，往遇之則吉。象曰：「豐其蔀」，位不當也。以居位不當，宜自蔽其明。「日中見鬥」，幽不明也。謂日既中，鬥不應有明也。往遇夷主，則以明歸君，是以吉行也。</p><p>六五：來章，有慶譽，吉。象曰：六五之吉，有慶也。六五為日中之主，天下之明盡來歸之，故曰「來章」。所謂「室家種葵藿」是也。不惟得位，又且得名，故曰「有慶譽，吉」。象曰：六五之「吉」，有慶也。所謂「王假尚大，宜照天下」，皆在此爻，宜其「有慶」也。</p><p>上六：豐其屋，蔀其家，𬮭其戶，闃其無人，三歲不覿㓙。象曰：「豐其屋」，天際翔也；「𬮭其戶，闃其無人」，自藏也。</p><p>上六居卦之外，不受六五之照臨者也。既豐其屋，又蔀其家，深自掩蔽，自處於覆盆之下，怡聲屏氣，視之若無人焉。然日中之主出矣，豈容其偃然自大？若三歲不覿，則六師夷之矣。以堯舜之世，十日在上，而三子偃然於蓬艾之間，雖堯舜不能釋然於南面，況下於堯舜者哉？「三歲不覿」，是自取㓙也。象曰：「豐其屋」，天際翔也。「𬮭其戶，闃其無人」，自藏也。䷷ 艮下離上</p><p>旅</p><p>旅：小亨，旅貞吉。彖曰：「旅，小亨」，柔得中乎外而順乎剛，止而麗乎明，是以「小亨，旅貞吉」也。旅之時義大矣哉！旅，商旅之道也。商旅，至微也，聖人設卦，安用屑屑於商旅哉？古者四民，商居其一。洪範八政，繼食以貨。蓋懋遷有無，阜通貨賄，亦有國者之先務也。凡旅，行者為商，坐者為賈，總名之「旅」也。卦辭「小亨」，言「旅貞吉」，又言「旅」，與他卦辭異者，以卦中有二「旅」者也。有出塗之旅，行商是也；有坐肆之旅，坐賈是也。卦艮下離上，離明乎外，艮止乎內。「小亨」，在外之旅，出塗之旅也；「貞吉」，在內之旅，坐肆之旅也。內旅貴處，艮止之義；外旅貴出，離明之義。明而出則亨，止而處則貞，故外卦三爻貴出，內卦三爻貴處。彖：「柔得中乎外而順乎剛」，外旅之事也。六五一柔麗乎二剛之間，非順不能也。「止而麗乎明」，內旅之事也。下體雖止，非麗乎上體之明，則無以通遠方之貨。惟其如此，故外者「小亨」，而內者「貞吉」也。</p><p>象曰：山上有火，旅；君子以明慎用刑而不留獄。</p><p>「山上有火」，明足以及遠。商旅覘四方物賈之低昂而操其利，非明足以見遠不能也。君子觀旅之象，「明謹用刑而不留獄」，蓋貨財貴阜通，而刑獄不欲積滯也。財利君子不言，故體其象以明獄。</p><p>初六，旅瑣瑣，斯其所取災。象曰：「旅瑣瑣」，志窮災也。六在下，最賤旅之童僕也，為言待童僕之道。人之待童僕，苟屑屑焉惟豪末是計，則其下必不安，而反有脫遺之患，故曰：「旅瑣瑣，斯其所取災。」象曰：「志窮災也。」童僕之志窮，則為變矣。六二，旅即次，懷其資，得童僕，貞。象曰：「得童僕貞」，終無尤也。</p><p>在內為坐肆之旅，二爻當之，故曰「旅即次」。即其資而次止也，故其資不散。童僕在下，切近於己而已，得之則可以貞守而吉也。象曰：終無尤也。</p><p>九三，旅焚其次，喪其童僕，貞厲。象曰：「旅焚其次」，亦以傷矣；以旅與下，其義喪也。</p><p>三，下體宜處者也，上繫於離，離，火也，為離所焚，故「旅焚其次」。其次既焚，童僕亦喪。蓋童僕已為二得，已不能有取也。既焚且喪，雖貞亦厲。象曰：「旅焚其次」，亦以傷矣；以旅與下，其義喪也。</p><p>九四，旅於處，得其資斧，我心不快。象曰：「旅於處」，未得位也；「得其資斧」，心未快也。</p><p>四，上體宜出者也，下連於艮，艮，止也，為艮所止，故曰「旅於處」。宜出而處，何以獲利？但得其資斧而已，故其心不愜快。象曰：「旅於處」，未得位也，以未至五也。「得其資斧」，心未快也。</p><p>六五，射雉，一矢亡，終以譽命。象曰：「終以譽命」，上逮也。上卦為在外之旅，五當之。旅，乘時射利者也，如射雉然，不靳一矢之亡，然後可以得禽；必委千金之資，然後可以謀什百之利。亡矢得禽，委資而得利，旅道之善也，然後可以當富商巨賈之名，故「終以譽命」。象曰「上逮也」，謂有道以至此也。</p><p>上九：鳥焚其巢，旅人先笑後號啕。喪牛於易，兇。象曰：以旅在上，其義焚也；「喪牛於易」，終莫之聞也。</p><p>五既得譽，可以貞守矣，而利心無厭，處離之極，乃焚其巢，拔援不已，義必喪也。方其焚也，以身免為喜，故「先笑」；及其定也，資斧皆喪，莫之追悔，故「後號啕」。牛所以載資斧也，牛既喪，則資斧喪可知。聖人故戒之曰：所以喪牛者，以利心拔援，不能持重，故曰「喪牛於易」。象以旅在上，其義焚也，謂拔援不止，義當焚也；「喪牛於易」，終莫之閒也。人之利心不可過，雖戒之以輕喪，終如不聞也。聖人設此義，後世謀利者莫不脗合。䷸ 巽下巽上</p><p>巽：</p><p>「巽」：小亨，利有攸往，利見大人。彖曰：重巽以申命。剛巽乎中正而志行，柔皆順乎剛，是以「小亨，利有攸往，利見大人」。</p><p>「巽」，順也，下也。柔行巽入之道，小人之事不可以常也。「巽」為風，為君者體之以出令，上以言巽下，下因言以巽上，則不害其為「巽」。故「巽」之道，在上行之則為恭、為謙、為敬有禮，在下行之則為諂、為佞、為巧言、令色、足恭。六爻綱領亦取此為義。上三爻，在上者之「巽」也，故上三爻皆善；下三爻，在下者之「巽」也，故下三爻皆未善。曰「巽」。「小亨」，以柔巽人，非大亨之道。「利有攸往」，柔行巽入，無往而不可。「利見大人」，見君之初，未可求深，故雍容和緩，為告君之體，然不可以順為正，為小亨之道也，所謂「仁言不如仁聲之入人深」也。彖言「重巽以申命」，亦小亨之道也。卦二、五剛皆得中，以「巽」而吉，二柔處四剛之下，皆順乎剛，體上下二卦之義，乃善於用「巽」者，是以「小亨，利有攸往，利見大人」者之所為也。</p><p>象曰：隨風，「巽」；君子以申命行事。象義甚明。</p><p>初六，進退，利武人之貞。象曰：「進退」，志疑也。「利武人之貞」，志治也。</p><p>「進退」，趑趄囁嚅之象也。以柔處下而「巽」乎上，其行進退，易流於諂，濟之以剛，猶無害也，故「利武人之貞」。象曰：「進退」，志疑也；「利武人之貞」，志治也。人惟以志為帥，則不為血氣所動。</p><p>九二，巽在床下，用史巫紛若，吉，無咎。象曰：「紛若」之「吉」，得中也。</p><p>二處重巽，「巽在床下」，過於「巽」也。以九居二，猶為得中，小亨可也，故用之史巫繁縟之禮則吉，亦非君子事神之道。象曰：得中也。九三，頻巽，吝。象曰：「頻巽」之「吝」，志窮也。</p><p>三處重巽之間，「巽」而又「巽」，以「巽」為常者也。已不中正，以「巽」為常，吝道也。象曰：「頻巽」之「吝」，志窮也。</p><p>六四，悔亡，田獲三品。象曰：「田獲三品」，有功也。</p><p>四與五在上體，處上而巽，不害為恭。四以柔處眾剛之間，以「巽」得上下之心，故曰「田獲三品」。田獵得禽，一乾豆，二賓客，三充君之庖，故象曰「有功也」。</p><p>九五：貞吉，悔亡，無不利。無初有終。先庚三日，後庚三日，吉。象曰：「九五」之「吉」，位正中也。</p><p>以居位處「巽」而得中，居上而下下，君德之善也，故「貞吉，悔亡，無不利」。君之巽下，必以言重「巽」申命。未從而命，是「無初」也；既命而從，是「有終」也。「先庚三日，後庚三日」，申命之道也。先庚三日而得丁，「後庚三日」而得癸，人君申命，必須大吉天下，使明知上意，然後陳揆而行之，故大盛於丁，而陳揆於癸也。</p><p>上九：巽在床下，喪其資斧，貞兇。象曰：「巽在床下」，上窮也；「喪其資斧」，正乎兇也。</p><p>處「巽」之極，過乎「巽」也。在上而「巽」，固「巽」之善；用「巽」而過，又正乎兇。二處下體，「巽在床下」，未害也；己處上體，「巽在床下」，則反失威重，並其資斧喪之矣。古人有行之者，夷王下堂見諸侯，未害為恭也，而諸侯反不至，正謂此也。象曰：「巽」在下，工窮也。「喪其資斧」，正乎兇也。西溪易說卷十一，</p>',97)])])}const x=a(i,[["render",r]]);export{m as __pageData,x as default};
